// Seed 2: Branchless optimized pack/unpack
// Uses bitwise tricks to avoid branching for sign extension.

fn pack_voxel(mat: u32, thermal: u32, kx: i32, ky: i32, phase: u32, flags: u32) -> u32 {
    // Single expression pack — compiler can fuse these
    return ((mat & MATERIAL_MASK) << MATERIAL_SHIFT)
         | ((thermal & THERMAL_MASK) << THERMAL_SHIFT)
         | ((u32(kx) & KINETIC_X_MASK) << KINETIC_X_SHIFT)
         | ((u32(ky) & KINETIC_Y_MASK) << KINETIC_Y_SHIFT)
         | ((phase & PHASE_MASK) << PHASE_SHIFT)
         | ((flags & FLAGS_MASK) << FLAGS_SHIFT);
}

fn unpack_voxel(packed: u32) -> VoxelState {
    var state: VoxelState;
    state.material = (packed >> MATERIAL_SHIFT) & MATERIAL_MASK;
    state.thermal = (packed >> THERMAL_SHIFT) & THERMAL_MASK;

    // Branchless sign extension: (val ^ 0x8) - 0x8 converts 4-bit unsigned to signed
    let kx_raw = (packed >> KINETIC_X_SHIFT) & KINETIC_X_MASK;
    let ky_raw = (packed >> KINETIC_Y_SHIFT) & KINETIC_Y_MASK;
    state.kinetic_x = i32((kx_raw ^ 0x8u) - 0x8u);
    state.kinetic_y = i32((ky_raw ^ 0x8u) - 0x8u);

    state.phase = (packed >> PHASE_SHIFT) & PHASE_MASK;
    state.flags = (packed >> FLAGS_SHIFT) & FLAGS_MASK;
    return state;
}

fn exchange_thermal(a: u32, b: u32) -> vec2<u32> {
    // Branchless thermal exchange with configurable rate
    let ta = (a >> THERMAL_SHIFT) & THERMAL_MASK;
    let tb = (b >> THERMAL_SHIFT) & THERMAL_MASK;

    // Arithmetic shift for signed division
    let diff = i32(ta) - i32(tb);
    let transfer = diff >> 2;  // Divide by 4 via shift

    let new_ta = u32(max(min(i32(ta) - transfer, 255), 0));
    let new_tb = u32(max(min(i32(tb) + transfer, 255), 0));

    let clear_mask = ~(THERMAL_MASK << THERMAL_SHIFT);
    return vec2<u32>(
        (a & clear_mask) | (new_ta << THERMAL_SHIFT),
        (b & clear_mask) | (new_tb << THERMAL_SHIFT)
    );
}

// ── Compute entry point ────────────────────────────────────────────

@group(0) @binding(0) var<storage, read> input: array<u32>;
@group(0) @binding(1) var<storage, read_write> output: array<u32>;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let idx = gid.x;
    if (idx >= arrayLength(&input)) {
        return;
    }

    let packed = input[idx];
    let state = unpack_voxel(packed);
    let repacked = pack_voxel(
        state.material, state.thermal,
        state.kinetic_x, state.kinetic_y,
        state.phase, state.flags
    );
    output[idx] = repacked;
}

// ca-v2: finite heat exchange across disjoint cardinal pairs.
override THERMAL_AXIS: u32 = 0u;
override THERMAL_PARITY: u32 = 0u;

@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    if (gid.x >= GRID_WIDTH || gid.y >= GRID_HEIGHT) { return; }
    let index = gid.y * GRID_WIDTH + gid.x;
    let coordinate = select(gid.x, gid.y, THERMAL_AXIS == 1u);
    let extent = select(GRID_WIDTH, GRID_HEIGHT, THERMAL_AXIS == 1u);
    let stride = select(1u, GRID_WIDTH, THERMAL_AXIS == 1u);
    var energy = energy_in[index];
    if (coordinate >= THERMAL_PARITY) {
        if ((coordinate - THERMAL_PARITY) % 2u == 0u) {
            if (coordinate + 1u < extent) { energy = pair_energy(io_state(index), io_state(index + stride)); }
        } else {
            energy = pair_energy(io_state(index), io_state(index - stride));
        }
    }
    io_write(index, grid_in[index], energy);
}

// Conservative diagonal matter fall.
//
// Each pass partitions the grid into disjoint 2x2 cells. One diagonal edge in
// each block is eligible, chosen by a deterministic hash and MOVE_SALT. This
// preserves exact per-material counts without atomics.


const COLD_STRIDE: u32 = 24u;
const COLD_DENSITY: u32 = 0u;
override MOVE_PHASE: u32 = 0u;
override MOVE_SALT: u32 = 0u;

fn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }
fn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }
fn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }

fn density_of(mat: u32) -> u32 {
    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];
}

fn is_structural(ph: u32) -> bool {
    return ph == PHASE_SOLID || ph == PHASE_FROZEN;
}

fn is_falling_matter(ph: u32) -> bool {
    return ph == PHASE_POWDER || ph == PHASE_LIQUID || ph == PHASE_VISCOUS || ph == PHASE_MOLTEN;
}

fn vertical_blocked(x: u32, y: u32, src: u32) -> bool {
    if (y >= GRID_HEIGHT - 1u) { return true; }
    return !io_can_fall(get_idx(x, y), get_idx(x, y + 1u));
}

fn hash_pair(x: u32, y: u32, salt: u32) -> u32 {
    var h = x * 374761393u + y * 668265263u + salt * 1442695041u;
    h = (h ^ (h >> 13u)) * 1274126177u;
    return h ^ (h >> 16u);
}

fn should_swap(src_x: u32, src_y: u32, dst_x: u32, dst_y: u32) -> bool {
    let src = grid_in[get_idx(src_x, src_y)];
    let dst = grid_in[get_idx(dst_x, dst_y)];
    return vertical_blocked(src_x, src_y, src) && io_can_fall(get_idx(src_x, src_y), get_idx(dst_x, dst_y));
}

@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }

    let idx = get_idx(x, y);
    let voxel = grid_in[idx];

    var upper_y = y;
    if ((y & 1u) != MOVE_PHASE) {
        if (y == 0u) {
            io_copy(idx, idx);
            return;
        }
        upper_y = y - 1u;
    }
    if (upper_y >= GRID_HEIGHT - 1u) {
        io_copy(idx, idx);
        return;
    }

    let pair_left = x - (x & 1u);
    if (pair_left >= GRID_WIDTH - 1u) {
        io_copy(idx, idx);
        return;
    }

    let prefer_right = (hash_pair(pair_left, upper_y, MOVE_SALT) & 1u) == 0u;
    let src_x = select(pair_left + 1u, pair_left, prefer_right);
    let dst_x = select(pair_left, pair_left + 1u, prefer_right);
    let src_y = upper_y;
    let dst_y = upper_y + 1u;
    let do_swap = should_swap(src_x, src_y, dst_x, dst_y);

    if (do_swap && x == src_x && y == src_y) {
        io_copy(idx, get_idx(dst_x, dst_y));
        return;
    }
    if (do_swap && x == dst_x && y == dst_y) {
        io_copy(idx, get_idx(src_x, src_y));
        return;
    }

    io_copy(idx, idx);
}

// Conservative thermal gas buoyancy.
//
// Non-air gas/plasma can rise through air or other gas when its thermal
// buoyancy rank is sufficiently higher than the upper target.


const COLD_STRIDE: u32 = 24u;
const COLD_DENSITY: u32 = 0u;
const GAS_RISE_THRESHOLD: i32 = 16;
override MOVE_PHASE: u32 = 0u;

fn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }
fn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }
fn get_thermal(p: u32) -> u32 { return (p >> THERMAL_SHIFT) & THERMAL_MASK; }
fn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }

fn density_of(mat: u32) -> u32 {
    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];
}

fn is_structural(ph: u32) -> bool {
    return ph == PHASE_SOLID || ph == PHASE_FROZEN;
}

fn is_gas_like(ph: u32) -> bool {
    return ph == PHASE_GAS || ph == PHASE_PLASMA;
}

fn gas_rank(index: u32) -> i32 {
    let v = grid_in[index];
    return i32(temperature_q(io_state(index)) / 256u) * 2 - i32(density_of(get_material(v)));
}

fn can_rise(src_idx: u32, dst_idx: u32) -> bool {
    let src = grid_in[src_idx];
    let dst = grid_in[dst_idx];
    let src_mat = get_material(src);
    let src_phase = get_phase(src);
    let dst_phase = get_phase(dst);
    if (src_mat == MAT_AIR || !is_gas_like(src_phase) || is_structural(dst_phase)) {
        return false;
    }
    if (get_material(dst) != MAT_AIR && !is_gas_like(dst_phase)) {
        return false;
    }
    return gas_rank(src_idx) > gas_rank(dst_idx) + GAS_RISE_THRESHOLD;
}

@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }

    let idx = get_idx(x, y);
    let voxel = grid_in[idx];

    if (y < GRID_HEIGHT - 1u && ((y & 1u) == MOVE_PHASE)) {
        let lower = grid_in[get_idx(x, y + 1u)];
        if (can_rise(get_idx(x, y + 1u), idx)) {
            io_copy(idx, get_idx(x, y + 1u));
            return;
        }
    }

    if (y > 0u && (((y - 1u) & 1u) == MOVE_PHASE)) {
        let upper = grid_in[get_idx(x, y - 1u)];
        if (can_rise(idx, get_idx(x, y - 1u))) {
            io_copy(idx, get_idx(x, y - 1u));
            return;
        }
    }

    io_copy(idx, idx);
}

// Conservative horizontal gas spread.
//
// Non-air gas/plasma spreads sideways through air/gas when upward buoyancy is
// blocked. Pair ownership is disjoint and salted to avoid one-way drift.


